insert into public.statutory_parameters
  (key, value, effective_from, effective_to, statute, section_ref, source_ref, notes, verified)
values
  ('gst.qrmp_turnover_limit', '{"amount":50000000}'::jsonb, '2021-01-01'::date, null, 'Central Goods and Services Tax Act, 2017', 's.39(1) proviso; Rule 61A', 'Notification 84/2020-Central Tax dated 10 Nov 2020 (QRMP scheme)', 'Aggregate turnover up to ₹5 crore is eligible for QRMP (quarterly GSTR-1 and GSTR-3B, monthly PMT-06); above that, monthly is mandatory. With no turnover recorded, the app defaults to monthly (§6.6).', true),
  ('itr.tax_audit.business', '{"limit":10000000,"limitLowCash":100000000,"cashShareMaxPct":5}'::jsonb, '2020-04-01'::date, '2026-03-31'::date, 'Income-tax Act, 1961', 's.44AB(a) and its proviso', 'Finance Act, 2021 (₹10 crore where cash receipts and cash payments are each within 5%)', 'Business: audit indicated above ₹1 crore turnover; the limit is ₹10 crore where cash receipts and cash payments are each 5% or less of the total (§6.6).', true),
